(function(){'use strict';function initVideoPlayers(){const videos=document.querySelectorAll('.meme-content-video');videos.forEach(video=>{video.addEventListener('loadstart',function(){this.classList.add('loading');});video.addEventListener('loadeddata',function(){this.classList.remove('loading');});video.addEventListener('error',function(e){console.error('Video load error:',e);handleVideoError(this);});video.addEventListener('play',function(){if(typeof gtag !=='undefined'){gtag('event','video_play',{video_src:this.src});}});video.addEventListener('dblclick',function(){if(this.requestFullscreen){this.requestFullscreen();}else if(this.webkitRequestFullscreen){this.webkitRequestFullscreen();}});});}function handleVideoError(videoElement){const container=videoElement.parentElement;const videoUrl=videoElement.src;const errorDiv=document.createElement('div');errorDiv.className='video-error';errorDiv.innerHTML=` <div style="padding:2rem;text-align:center;background:#f5f5f5;border-radius:8px;"> <p style="margin-bottom:1rem;font-size:1.1rem;">⚠️ Video failed to load</p> <a href="${videoUrl}" target="_blank" class="btn btn-primary" style="display:inline-block;padding:0.5rem 1rem;background:#1976d2;color:white;text-decoration:none;border-radius:4px;"> Open Video in New Tab </a> </div> `;videoElement.style.display='none';container.appendChild(errorDiv);if(typeof gtag !=='undefined'){gtag('event','video_error',{video_src:videoUrl,error_code:videoElement.error?.code || 'unknown'});}}if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',initVideoPlayers);}else{initVideoPlayers();}window.addEventListener('memeLoaded',initVideoPlayers);})();